import pandas as pd,numpy as np,glob
from scipy.signal import lfilter
files=sorted(glob.glob('train/*.csv'))
def load(f):
    d=pd.read_csv(f); t=d.time_s.values; dt=t[1]-t[0]
    return dict(t=t,dt=dt,P=d.active_power_pu.values,Q=d.reactive_power_pu.values,V=d.voltage_pu.values,th=d.bus_angle_rad.values,S=d.voltage_setpoint_pu.values)
D={f:load(f) for f in files}
def washout(x,Tw,dt):
    # wash: y = (x - lp)/... with lp first-order LP of x, y = x-lp  (highpass)
    a=dt/(Tw+dt); lp=lfilter([a],[1,-(1-a)],x); return x-lp
def lag(x,T,dt):
    a=dt/(T+dt); return lfilter([a],[1,-(1-a)],x)
for Tw in [0.5,2,5]:
    rows=[]
    for f,d in D.items():
        dt=d['dt']; dV=d['V']-d['V'][0]; dS=d['S']-d['S'][0]; wsh=washout(d['th'],Tw,dt)
        dP=d['P']-d['P'][0]; dQ=d['Q']-d['Q'][0]
        rows.append((dV,dS,wsh,dP,dQ))
    A=np.vstack([np.column_stack(r[:3]) for r in rows]); yP=np.concatenate([r[3] for r in rows]); yQ=np.concatenate([r[4] for r in rows])
